// Fit the landing composition to the available frame without scaling text.
const homeFrame=document.getElementById('home'),sceneSlot=homeFrame.querySelector('.scene-slot');homeFrame.querySelector('.hero-copy').after(sceneSlot);
function fitFrame(){if(homeFrame.hidden)return;const mast=document.querySelector('.masthead').getBoundingClientRect().height;homeFrame.style.height=`${Math.max(0,innerHeight-mast)}px`;const available=sceneSlot.parentElement.getBoundingClientRect().width-32;let w=Math.min(760,available);sceneSlot.style.width=w+'px';const room=sceneSlot.clientHeight;for(let i=0;i<5;i++){cabinetScene.style.width=w+'px';const sceneR=cabinetScene.getBoundingClientRect(),tableR=cabinetScene.querySelector('.shared-table').getBoundingClientRect();const needed=tableR.bottom-sceneR.top+44;if(needed<=room)break;w=Math.max(248,w-(needed-room)*1.6)}cabinetScene.style.width=w+'px';sceneSlot.style.width=Math.min(available,w)+'px';requestAnimationFrame(placeTrackHints)}
addEventListener('resize',fitFrame);document.fonts.ready.then(fitFrame);addEventListener('hashchange',()=>requestAnimationFrame(fitFrame));requestAnimationFrame(fitFrame);
